shell('addons.html','Choose optional cover',heading('OPTIONS / PLAN CONFIGURATION','Choose what belongs in your cover.','Check each benefit, restriction and price before adding it.')+notice('Configuration preview','These benefits demonstrate the interaction. Actual availability and prices must come from the selected insurer, plan, variant and source version. No insurer offer is represented.','paper')+'''<div class="two-column"><article class="document"><h2>Base cover and optional benefits</h2><div class="summary-row"><h3>Included cover</h3><p>Show sourced base benefits here. Included benefits are retained; they are not an optional charge.</p></div><fieldset><legend>Optional benefits — none selected</legend><label class="check"><input type="checkbox"> Example optional benefit A</label><p>Benefit and limits: source required. Additional premium: not available.</p><a href="addon-details.html">Read eligibility and exclusions</a><label class="check"><input type="checkbox"> Example optional benefit B</label><p>Check whether this benefit overlaps another selected option.</p></fieldset><a href="bundle.html">Review a bundled configuration</a></article><aside class="sticky-panel"><h2>Your configuration</h2><dl class="definition-list"><div><dt>Base premium</dt><dd>Source required</dd></div><div><dt>Selected options</dt><dd>None in the fixed preview</dd></div><div><dt>Taxes / total</dt><dd>Not available</dd></div></dl><button disabled>Continue with verified total</button><a class="button secondary" href="addons-review.html">Preview selection review</a><a class="text-link" href="addon-unavailable.html">Preview an incompatible option</a></aside></div>''','SCR-OPTIONS/SELECT',[1,6,9,23,49],2,True)

shell('addon-details.html','Optional benefit details',heading('OPTION DETAILS','Read the boundary of the benefit.','Use the exact selected plan’s source wording.')+'''<article class="document"><h2>Example optional benefit A</h2><dl class="definition-list"><div><dt>What it adds</dt><dd>Source-defined benefit and limit required</dd></div><div><dt>Who can select it</dt><dd>Age, vehicle, geography or other eligibility conditions required</dd></div><div><dt>Not included</dt><dd>Material exclusions and waiting periods required</dd></div><div><dt>Dependencies / conflicts</dt><dd>Required base cover and incompatible options must be supplied</dd></div><div><dt>Additional premium</dt><dd>Unknown — do not estimate by splitting a bundle</dd></div><div><dt>Source and effective version</dt><dd>Not supplied for this layout example</dd></div></dl><a class="button secondary" href="addons.html">Back to options</a></article>''','SCR-OPTIONS/DETAIL',[6,9,24,49],2,True)

shell('bundle.html','Review a bundle',heading('BUNDLED COVER','One configuration. Read every part.','A bundle price does not reveal the price of every component.')+'''<section class="document"><h2>Example bundle</h2><p>Show the insurer’s bundle name and version, included options, eligibility and whether components can be removed.</p><div class="table-wrap"><table><thead><tr><th>Component</th><th>Selection rule</th><th>Price evidence</th></tr></thead><tbody><tr><td>Base plan</td><td>Required</td><td>Source required</td></tr><tr><td>Included benefit</td><td>Included in this bundle</td><td>Not separately supplied</td></tr><tr><td>Optional extra</td><td>Deliberate opt-in, if eligible</td><td>Source required</td></tr></tbody></table></div><p>Bundle total: unavailable. Savings claims require a comparable, current standalone configuration.</p><a class="button secondary" href="addons-review.html">Preview configuration comparison</a></section>''','SCR-OPTIONS/BUNDLE',[6,9,24,49],2,True)

shell('addons-review.html','Review selected cover',heading('CONFIGURATION REVIEW','Compare the cover you selected.','A lower base premium may have different benefits from the selected configuration.')+'''<div class="table-wrap"><table><thead><tr><th>Review item</th><th>Base configuration</th><th>Selected configuration</th></tr></thead><tbody><tr><th>Base cover</th><td>Source required</td><td>Same source version required</td></tr><tr><th>Optional benefits</th><td>None</td><td>Example benefit A — preview only</td></tr><tr><th>Limits and exclusions</th><td>Read exact wording</td><td>Read base and optional benefit wording</td></tr><tr><th>Premium / taxes / total</th><td>Not available</td><td>Not available</td></tr><tr><th>Equivalent comparison?</th><td colspan="2">Check all selected benefits, limits, term, frequency, tax and source version.</td></tr></tbody></table></div><div class="actions"><a class="button" href="summary.html">Before-you-buy summary</a><a class="button secondary" href="addons.html">Edit options</a><a class="text-link" href="addon-change.html">Preview a change after payment</a></div>''','SCR-OPTIONS/REVIEW',[9,23,24,49],2,True)

shell('addon-unavailable.html','Option cannot be combined',heading('OPTIONS / CHECK SELECTION','These options cannot be combined.','Your previous configuration has been kept.')+notice('Review the source rule','Explain the exact conflict or unmet eligibility condition. Never remove or replace paid cover silently.','yellow')+'''<section class="paper-panel"><h2>Choose how to continue</h2><p>Return to the options and select a supported configuration. If the source rule is unclear, keep the option unresolved and ask for help.</p><a class="button secondary" href="addons.html">Review options</a><a class="text-link" href="help.html">Get help</a></section>''','SCR-OPTIONS/INCOMPATIBLE',[6,9,23,49],2,True,'Incompatible')

shell('addon-change.html','Change options after payment',heading('ONBOARDING / CHANGE COVER','Review the option change before accepting.','Changing an add-on or bundle can change both benefits and premium.')+'''<div class="table-wrap"><table><thead><tr><th>Item</th><th>Previously accepted</th><th>Edited selection</th></tr></thead><tbody><tr><th>Optional benefit A</th><td>Not selected</td><td>Selected, eligibility pending</td></tr><tr><th>Benefits and exclusions</th><td>Original source revision retained</td><td>New source review required</td></tr><tr><th>Total premium</th><td>Recorded accepted quote</td><td>Requote required</td></tr></tbody></table></div><p>Your confirmed payment stays in the history. A verified increase creates a separate balance payment; a verified decrease creates a tracked refund. Pending adjustments must be reconciled first.</p><div class="actions"><a class="button secondary" href="repricing.html">Preview revised amount review</a><a class="text-link" href="onboarding.html">Keep current configuration</a></div>''','SCR-OPTIONS/POSTPAYMENT',[3,4,9,12,30,32,49],4,True)

# Add configuration entry points without presenting fixtures as real offers.
for item in list(pages):
    if item['file'] in ['health.html','term.html','motor.html','ulip.html','summary.html','term-summary.html','motor-summary.html','ulip-summary.html','onboarding.html']:
        file=OUT/item['file']
        source=file.read_text().replace('<aside class="premium-note"','<div class="actions"><a class="button secondary" href="addons.html">Review add-ons and bundles</a></div><aside class="premium-note"',1)
        file.write_text(source)
